  ui_story_30790101_139_dialog_content = "...Así veo.",
  ui_story_30790101_140_dialog_content = "Fue mi negligencia.",
  ui_story_30790101_141_dialog_content = "No, no fue negligencia. Como asesor, he... cometido un error imperdonable.",
  ui_story_30790101_142_dialog_content = "Gracias, PlayerName, por señalar mi punto ciego.",
