  ui_story_30790101_144_dialog_content = "*Michenny se va*",
  ui_story_30790101_145_dialog_content = "Uf, ¿la enviaste así no más, PlayerName?¿Eh?",
  ui_story_30790101_146_dialog_content = "¿Ah?",
  ui_story_30790101_147_dialog_content = "Se suponía que me pagarías porque me deslice.",
  ui_story_30790101_148_dialog_content = "Pero simplemente la hiciste sentir culpable y te salvaste de la deuda.",
  ui_story_30790101_149_dialog_content = "No me expongas. ¿O tendré que pagarte a una tasa de diez Nightiums por centímetro?",
  ui_story_30790101_150_dialog_content = "No veo porque no.",
  ui_story_30790101_151_dialog_content = "Ahórrame.",
  ui_story_30790601_1_dialog_content = "PlayerName, finalmente te encontré.",
  ui_story_30790601_2_dialog_content = "... Michenny? No te reconocí con ese atuendo puesto.",
  ui_story_30790601_3_dialog_content = "Realmente solo quería consultarte sobre mi atuendo. Y te compensaré por tu tiempo.",
  ui_story_30790601_4_dialog_content = "¿Vestimenta? ¿Compensación? ¿De qué estás hablando?",
  ui_story_30790601_5_dialog_content = "Planeaba ir al Desierto de Rediesel y pensé que este atuendo me ayudaría a mezclarme con el entorno. ¿Qué piensas?",
  ui_story_30790601_6_dialog_content = "¿Te escuché correctamente? ¿Vas al Desierto de Rediesel? Los nobles de Lumo casi nunca van allí.",
  ui_story_30790601_7_dialog_content = "Por favor, solo responde a mi pregunta: ¿este atuendo está bien?",
  ui_story_30790601_8_dialog_content = "Oh, es más que bien, te ves excelente.",
  ui_story_30790601_9_dialog_content = "Gracias, esta es tu recompensa por responder a mi pregunta: 100 Nightium.",
  ui_story_30790601_10_dialog_content = "¿Eh? ¿Quieres pagarme solo por responder una pregunta? No, gracias.",
  ui_story_30790601_11_dialog_content = "¿Así que prefieres una gema? Lamentablemente, el valor de este asunto no justifica del todo una gema.",
  ui_story_30790601_12_dialog_content = "Uh, no... olvídalo, tomaré el dinero, pero tú también tienes que responder una pregunta para mí... por 100 Nightium.",
  ui_story_30790601_13_dialog_content = "¿Por qué vas al Desierto de Rediesel?",
  ui_story_30790601_14_dialog_content = "Para este Dunecat.",
  ui_story_30790601_15_dialog_content = "¿Eh?",
  ui_story_30790601_16_dialog_content = "Maullar.",
  ui_story_30790601_17_dialog_content = "¡¿Qué?! ¿De dónde salió el gato?",
  ui_story_30790601_18_dialog_content = "Lo mencioné aquí.",
  ui_story_30790601_19_dialog_content = "¿Desde cuándo tienes un gato como mascota?",
  ui_story_30790601_20_dialog_content = "No es una mascota.",
  ui_story_30790601_21_dialog_content = "¿Entonces por qué lo tienes?",
  ui_story_30790601_22_dialog_content = "Fue atrapado por un traficante de animales en el Desierto de Rediesel, y su cabeza resultó herida durante la captura.",
  ui_story_30790601_23_dialog_content = "El traficante lo llevó a Lumopolis y lo vendió a un noble presumido que lo abandonó al lado del camino al descubrir la lesión en la cabeza.",
  ui_story_30790601_24_dialog_content = "Pasé por casualidad y vi lo que estaba pasando, así que arresté tanto al noble como al traficante.",
  ui_story_30790601_25_dialog_content = "¡Esos malditos traficantes de animales!",
  ui_story_30790601_26_dialog_content = "He respondido a cuatro de tus preguntas en total.",
  ui_story_30790601_27_dialog_content = "O-Okay, pagaré, pero no tengo nada encima ahora mismo. Te daré 100 Nightium primero, y el resto...",
  ui_story_30790601_28_dialog_content = "No hay necesidad, los estándares para tales cosas no están fijos, y no me importa flexibilizar las reglas al tratar con personas empobrecidas como tú. Solo los 100 Nightium serán suficientes.",
  ui_story_30790601_29_dialog_content = "¿I-Impoverished? Bueno... supongo que me atrapaste ahí...",
  ui_story_30790601_30_dialog_content = "Miau...",
  ui_story_30790601_31_dialog_content = "Al mirar los accesorios en este Dunecat, supongo que tiene un dueño, uno que debe estar muy ansioso en este momento.",
  ui_story_30790601_32_dialog_content = "Entonces, necesito enviarlo de regreso al desierto lo más pronto posible.",
  ui_story_30790601_33_dialog_content = "Iré contigo. Nunca has estado en el Desierto de Rediesel... Es bastante peligroso allí.",
  ui_story_30790601_34_dialog_content = "En ese caso... necesitaré hacer algunos cálculos.",
  ui_story_30790601_35_dialog_content = "¿De nuevo? Incluso sacaste las escamas...",
  ui_story_30790601_36_dialog_content = "Tarifa de escolta, gastos de viaje, gastos de seguridad personal, gastos médicos y el valor añadido de ser el último celestita en el mundo...",
  ui_story_30790601_37_dialog_content = "El costo es un poco demasiado alto. Debería ser fácil cubrirlo si solo es una pierna rota, pero si pierdes la vida...",
  ui_story_30790601_38_dialog_content = "¿Por qué asumes que algo malo me va a pasar?!",
  ui_story_30790601_39_dialog_content = "Los evaluadores deben considerar y medir todas las situaciones con precisión.",
  ui_story_30790601_40_dialog_content = "¡Solo piensa en ello como un amigo que te acompaña a hacer una buena acción, sin ningún costo o peligro!",
  ui_story_30790601_41_dialog_content = "De esa manera, necesito poner la amistad en un extremo de la balanza. Eso es aún más pesado.",
  ui_story_30790601_42_dialog_content = "No te compliques tanto. Con el tiempo que te tomó calcular todo esto, ya podríamos haber llevado este Dunecat a casa.",
  ui_story_30790601_43_dialog_content = "De hecho, olvidé considerar los gastos de tiempo justo ahora. Gracias por el recordatorio.",
  ui_story_30790601_44_dialog_content = "¡Está bien, está bien! Vamos a apresurarnos y salir ya.",
  ui_story_30790601_45_dialog_content = "Entonces, este es el Desierto de Rediesel.",
  ui_story_30790601_46_dialog_content = "Si. ¿Sabes dónde está la casa del Dunecat?",
  ui_story_30790601_47_dialog_content = "No, no lo hago.",
  ui_story_30790601_48_dialog_content = "Entonces, ¿cómo lo encontramos?",
  ui_story_30790601_49_dialog_content = "El Dunecat debería saberlo.",
  ui_story_30790601_50_dialog_content = "Así es, muchos animales pueden rastrear olores para encontrar su camino a casa.",
  ui_story_30790601_51_dialog_content = "Uh, ¿gatito? ¿Duney? ¿Gato-Gato?",
  ui_story_30790601_52_dialog_content = "Zzzz... miau...",
  ui_story_30790601_53_dialog_content = "Michenny, ¿cómo llamas a este gato, de todos modos?",
  ui_story_30790601_54_dialog_content = "Simplemente llámalo Dunecat.",
  ui_story_30790601_55_dialog_content = "Pero acabo de llamarlo y me ignoró por completo... Quizás deberíamos darle un nombre.",
  ui_story_30790601_56_dialog_content = "Darle un nombre sería como considerarlo una mascota. Nuestra relación simplemente equivale a la de acompañante más acompañado.",
  ui_story_30790601_57_dialog_content = "Está bien. Pensé que realmente te gustaba este gato.",
  ui_story_30790601_58_dialog_content = "La idea de \"gustar\" puede llevar fácilmente a la confusión. El juicio no requiere tales sentimientos.",
  ui_story_30790601_59_dialog_content = "Creo que el sol me está mareando... y tus teorías solo me hacen sentir peor. Creo que me voy a desmayar en cualquier momento.",
  ui_story_30790601_60_dialog_content = "Dunecat, ¿puedes encontrar tu hogar?",
  ui_story_30790601_61_dialog_content = "Miau... Zzzz...",
  ui_story_30790601_62_dialog_content = "Se dio la vuelta y volvió a quedarse dormido...",
  ui_story_30790601_63_dialog_content = "Los Dunecats son nocturnos, lo que significa que duermen durante el día y están principalmente activos por la noche. Parece que tendremos que esperar hasta el anochecer antes de que pueda guiarnos a su casa.",
  ui_story_30790601_64_dialog_content = "Tengo una sugerencia: podemos pedirle ayuda a Sinsa. Él es el líder de Rediesel Wrench.",
  ui_story_30790601_65_dialog_content = "Quizás puedan ayudarnos a encontrar el hogar del Dunecat, o al menos proporcionarnos alimento y refugio...",
  ui_story_30790601_66_dialog_content = "No, como noble, preferiría no tratar con esos bárbaros.",
  ui_story_30790601_67_dialog_content = "No los conoces, en realidad son personas muy agradables y necesitamos desesperadamente comida y agua en este momento.",
  ui_story_30790601_68_dialog_content = "Mi mamá me crió con entrenamiento en independencia desde que era un bebé, y fui seleccionado por el Salón de Justicia, entre otros, por mi comportamiento maduro y tranquilo.",
  ui_story_30790601_69_dialog_content = "Entonces, incluso aquí en el desierto, creo que puedo sobrevivir sin su ayuda.",
  ui_story_30790601_70_dialog_content = "De acuerdo, si ese es el caso, ¿qué propones que hagamos ahora?",
  ui_story_30790601_71_dialog_content = "Nuestra primera tarea debería ser encontrar una fuente de agua. Debemos buscar un oasis o cavar un pozo nosotros mismos.",
  ui_story_30790601_72_dialog_content = "Todo lo que puedo ver aquí es un mar interminable de dunas de arena. Ni siquiera hay un solo árbol, y mucho menos el más mínimo indicio de un oasis.",
  ui_story_30790601_73_dialog_content = "¿Y cómo se supone que cavaremos un pozo sin herramientas?",
  ui_story_30790601_74_dialog_content = "Cavaremos a mano. Al fin y al cabo, solo es arena.",
  ui_story_30790601_75_option_content = "Intenta cavar aquí",
  ui_story_30790601_76_dialog_content = "No hay nada aquí.",
  ui_story_30790601_77_option_content = "Intenta cavar de nuevo",
  ui_story_30790601_78_dialog_content = "La arena se derrumbó tan pronto como empecé a cavar.",
  ui_story_30790601_79_option_content = "El plan falló...",
  ui_story_30790601_80_dialog_content = "No podemos simplemente cavar a ciegas así y rezar por un milagro. Recuerdo haber leído algo sobre esto en un libro. Si ves musgo en el desierto, significa que hay mucha humedad cerca.",
  ui_story_30790601_81_dialog_content = "Solo excavando en las áreas húmedas podemos tener la oportunidad de encontrar agua subterránea.",
  ui_story_30790601_82_dialog_content = "Todo lo que puedo ver aquí son algunas plantas que parecen hierba marchita; sus raíces deberían contener algo de humedad. Voy a intentar arrancar algunas.",
  ui_story_30790601_83_dialog_content = "Toma, esto es para ti.",
  ui_story_30790601_84_dialog_content = "¿Estás seguro de que puedes comer estas raíces secas?",
  ui_story_30790601_85_dialog_content = "Por supuesto, esta es una planta del desierto. Debe contener agua.",
  ui_story_30790601_86_option_content = "Toma un mordisco",
  ui_story_30790601_87_dialog_content = "Bah, todo está arenoso.",
  ui_story_30790601_88_option_content = "El plan falló...",
  ui_story_30790601_89_dialog_content = "Se está haciendo tarde. Si el Dunecat no despierta o su lesión en la cabeza aún no ha sanado, tal vez necesitemos pasar la noche aquí.",
  ui_story_30790601_90_dialog_content = "Entonces, deberíamos buscar el Pecado—",
  ui_story_30790601_91_dialog_content = "Deberíamos construir un refugio simple, como una pequeña cabaña de troncos.",
  ui_story_30790601_92_dialog_content = "¿Una pequeña cabaña de troncos?! ¿Hablas en serio?",
  ui_story_30790601_93_dialog_content = "Sí. No soy uno de esos nobles sensibles e irracionales, todo lo que necesito es una simple cabaña de troncos.",
  ui_story_30790601_94_dialog_content = "Correcto, si Matthieu estuviera aquí, probablemente sugeriría que construyamos una casa dorada, mientras que tú simplemente quieres que los dos construyamos una cabaña de troncos con nuestras propias manos.",
  ui_story_30790601_95_dialog_content = "La única dificultad aquí es que no hay árboles grandes cerca.",
  ui_story_30790601_96_dialog_content = "¿Estás seguro de que esa es la ÚNICA dificultad?",
  ui_story_30790601_97_option_content = "El plan falló...",
  ui_story_30790601_98_dialog_content = "Bien, puedes llamar a alguien de Rediesel Wrench para que ayude. Yo les pagaré.",
  ui_story_30790601_99_dialog_content = "Pero no pueden decirle a nadie que los contraté. Este será un acuerdo puramente laboral entre desconocidos.",
  ui_story_30790601_100_dialog_content = "¿Cómo se supone que les explique algo así? No aceptarían trabajo de un noble tan altivo. Mejor olvídalo.",
  ui_story_30790601_101_dialog_content = "Miau...",
  ui_story_30790601_102_dialog_content = "¡El gato finalmente despertó!",
  ui_story_30790601_103_dialog_content = "¿Te sientes mejor, Dunecat? ¿Puedes encontrar el camino a casa ahora?",
  ui_story_30790601_104_dialog_content = "Miau, miau...",
  ui_story_30790601_105_dialog_content = "Puede moverse lentamente, pero parece que aún no se ha recuperado completamente.",
  ui_story_30790601_106_dialog_content = "Entonces déjalo avanzar a su propio ritmo.",
  ui_story_30790601_107_dialog_content = "Tus ojos no han dejado de mirar a ese gato ni un segundo mientras suenas completamente indiferente.",
  ui_story_30790601_108_dialog_content = "Bueno, no quisiera que se perdiera de nuevo.",
  ui_story_30790601_109_dialog_content = "¡Argh! ¡Ay, ay, ay!",
  ui_story_30790601_110_dialog_content = "¡Es un escorpión! ¡El bicho me está pellizcando y no me suelta!",
  ui_story_30790601_111_dialog_content = "¿Qué? ¿Qué debo hacer? ¡Y-yo te ayudaré a quitarlo!",
  ui_story_30790601_112_dialog_content = "¡No, no, no! ¡Me vas a arrancar la piel! ¡Argh! ¡Sus pinzas están apretando aún más fuerte ahora!",
  ui_story_30790601_113_dialog_content = "¡Miau!",
  ui_story_30790601_114_dialog_content = "¡¿Eh?! ¡El Dunegato golpeó a ese escorpión y simplemente soltó y huyó en un instante!",
  ui_story_30790601_115_dialog_content = "Está lamiendo tu herida, debe estar desinfectándola.",
  ui_story_30790601_116_dialog_content = "*sollozo* ¡Eres el mejor gato del mundo! ¡Salvaste mi vida!",
  ui_story_30790601_117_dialog_content = "...",
  ui_story_30790601_118_dialog_content = "¿Me lo imaginé? Rodó los ojos hacia mí, luego se dio la vuelta y se alejó...",
  ui_story_30790601_119_dialog_content = "De hecho, tampoco te soporta.",
  ui_story_30790601_120_dialog_content = "Ustedes dos me están dando exactamente la misma mirada ahora...",
  ui_story_30790601_121_dialog_content = "<color=#e8d9bb>*gruñido estomacal*</color>",
  ui_story_30790601_122_dialog_content = "¿Qué fue ese sonido?",
  ui_story_30790601_123_dialog_content = "Jaja, tienes hambre, escuché a tu estómago rugir. Pero yo también tengo hambre.",
  ui_story_30790601_124_dialog_content = "¿Qué es el hambre? Nunca he pasado hambre en mi vida.",
  ui_story_30790601_125_dialog_content = "Tu estómago dice lo contrario.",
  ui_story_30790601_126_dialog_content = "No, soy un noble elegante. Nunca tengo hambre.",
  ui_story_30790601_127_dialog_content = "<color=#e8d9bb>*groooowwwwl*</color>",
  ui_story_30790601_128_dialog_content = "Es aún más fuerte...",
  ui_story_30790601_129_dialog_content = "Yo-yo puedo tomarlo.",
  ui_story_30790601_130_dialog_content = "Maullar.",
  ui_story_30790601_131_dialog_content = "¿Mmm? El gato atrapó... ¿un ratón de campo? Lo colocó justo al frente de ti, como si intentara darte algo para comer.",
  ui_story_30790601_132_dialog_content = "Gracias, Dunecat, pero realmente no puedo comer este tipo de cosas.",
  ui_story_30790601_133_dialog_content = "Maullar.",
  ui_story_30790601_134_dialog_content = "Maullar.",
  ui_story_30790601_135_dialog_content = "¡Whoa! ¡Allá! ¡Es otro Dunegato!",
  ui_story_30790601_136_dialog_content = "¿Son amigos? May¿será que nos llevará a su hogar? ¡Se están acercando el uno al otro!",
  ui_story_30790601_137_dialog_content = "Ellos... ¿eh? Simplemente se asintieron el uno al otro y luego se separaron?",
  ui_story_30790601_138_dialog_content = "¿Eso significa que no son familia?",
  ui_story_30790601_139_dialog_content = "Esta es la naturaleza del Dunecat. Son cazadores solitarios que no necesitan un grupo o compañeros. Solo se ayudan y comunican entre sí cuando es necesario.",
  ui_story_30790601_140_dialog_content = "En serio... cuanto más veo, más parece que tú y estos Dunecats son exactamente iguales.",
  ui_story_30790601_141_dialog_content = "¡Miau, miau, miau!!!",
  ui_story_30790601_142_dialog_content = "¿Qué pasa, Dunecat?",
  ui_story_30790601_143_dialog_content = "¿Por qué hace ese sonido? Todo su pelo está de punta. ¿Siente peligro?",
  ui_story_30790601_144_dialog_content = "¡¡¡Miau!!!",
  ui_story_30790601_145_dialog_content = "Sus ojos... ¡El peligro está acechando detrás de nosotros!",
  ui_story_30790601_146_dialog_content = "¡Es una serpiente!",
  ui_story_30790601_147_dialog_content = "No, ¡es una enorme pitón! ¡Ahhhhhh!",
  ui_story_30790601_148_dialog_content = "¡No tengas miedo, Dunecat! ¡Deja de forcejear! ¡Ya no puedo sostenerlo más!",
  ui_story_30790601_149_dialog_content = "¡Está mostrando sus dientes al pitón, como si intentara protegerte!",
  ui_story_30790601_150_dialog_content = "¡Aquí, toma el Dunecat y corre! ¡Yo detendré a la pitón!",
  ui_story_30790601_151_dialog_content = "¿Cómo podría huir y dejarte atrás? ¡Salgamos de aquí juntos!",
  ui_story_30790601_152_dialog_content = "Las serpientes son enemigos naturales de los Dunegatos, así que seguro atacarán. ¡Por favor, lleva al gato lejos de aquí, rápido! ¡Solo puedo detenerlo por tanto tiempo!",
  ui_story_30790601_153_dialog_content = "Espera un segundo, hemos estado aquí hablando por tanto tiempo, y esta pitón ni siquiera nos ha atacado todavía.",
  ui_story_30790601_154_dialog_content = "Se ve un poco familiar.",
  ui_story_30790601_155_dialog_content = "Ah, eres tú, PlayerName.",
  ui_story_30790601_156_dialog_content = "Llevar a una encantadora dama a un lugar como este para una cita en medio de la noche, realmente es tu estilo.",
  ui_story_30790601_157_dialog_content = "¿Qué? ¿Cuándo he hecho algo siquiera remotamente parecido a eso?",
  ui_story_30790601_158_dialog_content = "Jejeje Es una broma.",
  ui_story_30790601_159_dialog_content = "¿Qué estás haciendo aquí? Por cierto, el python es tu altavoz, ¿verdad?",
  ui_story_30790601_160_dialog_content = "Simplemente estaba pasando cerca cuando mi Pitón Sagrada detectó algo inusual cerca y vino a investigarlo.",
  ui_story_30790601_161_dialog_content = "¡Nunca hubiera esperado que te atraparan haciendo algo malo!",
  ui_story_30790601_162_dialog_content = "No es así. Estamos haciendo una buena acción, ayudando a este gato a encontrar su casa.",
  ui_story_30790601_163_dialog_content = "Hmm, los adornos en este pequeño gato son muy especiales. Pertenecen a una tribu en lo profundo del desierto.",
  ui_story_30790601_164_dialog_content = "¿Sabes dónde está su casa?",
  ui_story_30790601_165_dialog_content = "Sí. Esa tribu es terriblemente misteriosa y tiene muy poco contacto con el mundo exterior. Creen en el Dios del Desierto y consideran al Dunecat como un mensajero de los cielos.",
  ui_story_30790601_166_dialog_content = "Eligen al Dunecat más hermoso cada año y lo adornan con ornamentos, considerándolo como su tótem y el símbolo sagrado de la tribu.",
  ui_story_30790601_167_dialog_content = "Entonces es un gato muy importante. ¿Puedes llevarnos a su tribu?",
  ui_story_30790601_168_dialog_content = "Me temo que no. Esa tribu es bastante hostil hacia los extraños. ¿Cómo encontraste este Dunecat de todos modos?",
  ui_story_30790601_169_dialog_content = "Michenny atrapó al malvado traficante que robó este gato en Lumopolis.",
  ui_story_30790601_170_dialog_content = "Entonces, fue robado. En ese caso, no puedes ir directamente a la tribu, ya que puede llevar a un malentendido desagradable e innecesario.",
  ui_story_30790601_171_dialog_content = "Llevaré el Dunecat de vuelta. Todavía tengo algunas conexiones con ellos y creerían lo que digo.",
  ui_story_30790601_172_dialog_content = "¡Eso suena como una idea brillante! ¿Qué opinas, Michenny?",
  ui_story_30790601_173_dialog_content = "Esta persona... ¿Realmente podemos confiar en ella con el gato?",
  ui_story_30790601_174_dialog_content = "Jeriah es un miembro senior de la Unión de Mensajería y también es una amiga mía. Definitivamente podemos confiar en ella.",
  ui_story_30790601_175_dialog_content = "¡Qué astuto de ti! ¡Pudiste darte cuenta de un vistazo que no soy confiable en absoluto!",
  ui_story_30790601_176_dialog_content = "No te enfades, Jeriah. Michenny solo está—",
  ui_story_30790601_177_dialog_content = "Está bien, cálmate. Deberías saber que no soy tan sensible.",
  ui_story_30790601_178_dialog_content = "... Bien. Por favor asegúrate de devolverlo con seguridad. Te pagaré.",
  ui_story_30790601_179_dialog_content = "Qué encantadora niña pequeña. Aunque está vestida para el desierto, habla como si estuviera en Lumopolis.",
  ui_story_30790601_180_dialog_content = "Ya que me has confiado este trabajo, considerémoslo como asunto oficial de la Unión de Mensajería.",
  ui_story_30790601_181_dialog_content = "Pero tendré que dejarlo a un lado por ahora, hasta que tenga tiempo para entregarlo.",
  ui_story_30790601_182_dialog_content = "¡De ninguna manera! ¡Este gato está herido! ¡Necesita regresar a su familia inmediatamente!",
  ui_story_30790601_183_dialog_content = "Te pagaré más... tanto como quieras.",
  ui_story_30790601_184_dialog_content = "Jeriah, sé que normalmente no haces este tipo de trabajos, pero este asunto del gato es algo así como una situación especial. Por favor...",
  ui_story_30790601_185_dialog_content = "Si es una solicitud de un amigo, por supuesto que puedo darle prioridad. Si es un trabajo, sin embargo...",
  ui_story_30790601_186_dialog_content = "Por favor, trata esto como una solicitud de un amigo. Aunque no sé si estarías dispuesto a considerarme como un amigo...",
  ui_story_30790601_187_dialog_content = "Entonces, la arrogante dama noble está dispuesta a renunciar a su estatus. Parece que realmente te importa este pequeño gato.",
  ui_story_30790601_188_dialog_content = "Por favor, Jeriah! Por favor, ayúdanos a llevar el gato a su casa. Yo—",
  ui_story_30790601_189_option_content = "¡Ponte una falda!",
  ui_story_30790601_190_dialog_content = "Oh... No puedo creer que estés dispuesto a llegar tan lejos...",
  ui_story_30790601_191_dialog_content = "Jeje, no hay manera de que deje pasar una oportunidad como esta.",
  ui_story_30790601_192_dialog_content = "¿Qué dije justo ahora?! ¿Cómo pude soltar algo así...",
  ui_story_30790601_193_option_content = "¡Maulla como un gato!",
  ui_story_30790601_194_dialog_content = "Déjame escuchar. Veamos si eres un lingüista de gatitos nato.",
  ui_story_30790601_195_dialog_content = "Miau... miau, miau... miau... Esto es vergonzoso...",
  ui_story_30790601_196_dialog_content = "Jeje, es bastante lindo.",
  ui_story_30790601_197_dialog_content = "Eso fue terriblemente vergonzoso, PlayerName, pero tanto el gato como yo estamos muy agradecidos contigo.",
  ui_story_30790601_198_dialog_content = "No es nada, todo para el gato... *sollozo*",
  ui_story_30790601_199_dialog_content = "Está bien, traeré al gato de vuelta sano y salvo en muy poco tiempo.",
  ui_story_30790601_200_dialog_content = "¡Genial! ¡Gracias!",
  ui_story_30790601_201_dialog_content = "Gracias.",
  ui_story_30790601_202_dialog_content = "Entonces, Michenny, es hora de despedirse del gatito.",
  ui_story_30790601_203_dialog_content = "Por favor, permíteme darle un último abrazo.",
  ui_story_30790601_204_dialog_content = "¡Miaaau!",
  ui_story_30790601_205_dialog_content = "Kitty, espero que te recuperes pronto. Te extrañaré.",
  ui_story_30790601_206_dialog_content = "(Michenny sostiene al Dunecat en sus brazos durante mucho tiempo, negándose a soltarlo. Sus ojos brillan con lo que parecen ser lágrimas.)",
  ui_story_30790601_207_dialog_content = "Michenny...",
  ui_story_30790601_208_dialog_content = "Estoy bien.",
  ui_story_30790601_209_dialog_content = "Adiós, Dunecat.",
  ui_story_30790601_210_dialog_content = "Maullar."
}
return config
